package com.wheelwright.evidence.v2;
import com.wheelwright.evidence.db.SqliteEvidenceStore;import com.wheelwright.evidence.v2.portfolio.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import java.nio.file.Path;import java.nio.charset.StandardCharsets;import java.util.*;
import static com.wheelwright.evidence.v2.portfolio.PortfolioJson.*;import static com.wheelwright.evidence.v2.portfolio.PortfolioRepository.*;import static org.assertj.core.api.Assertions.*;
class PortfolioFidelityBasisTest {
 @TempDir Path directory;
 String csv(String rows){return "Account number,Account name,Investment type,Symbol,Description,Quantity,Current value,Total gain/loss dollar,Type,Cost basis total,Average cost basis\n"+rows+"Date downloaded Oct-27-2026 at 12:15 p.m. ET\n";}
 @Test void exactSourceBasisSurvivesRetainedAdmissionAndRepeatedRefreshWithoutCreatingOpening()throws Exception{
  try(var db=new SqliteEvidenceStore(directory.resolve("source.db").toString())){var accounts=new AccountDirectory(db.getConnection().getMetaData().getURL());String a=accounts.bind("pine","A1");var artifacts=new BrokerageArtifacts(db.getConnection().getMetaData().getURL(),JSON,new PositionReadService(db,JSON));var input=csv("A1,Pine,ETFs,ABC,Shares,100,1240,-244,Cash,1484,14.84\nA1,Pine,Options,-ABC261120C15,Call,-1,-25,-10.66,Cash,14.34,0.14\n");assertThat(artifacts.ingest(a,"source.csv","POSITIONS",input.getBytes(StandardCharsets.UTF_8),UUID.randomUUID().toString()).status()).isEqualTo("ACCEPTED");var repo=new PortfolioRepository(db,JSON);var sources=new PortfolioSources(repo,JSON,accounts);sources.refresh(Set.of(a));var holdings=repo.list(Kind.HOLDING,Set.of(a));var service=new PortfolioReadService(repo,sources);var context=new PortfolioReadService.ReadContext();var caller=new BearerAuthenticator.Principal("test",Set.of("account.holdings.read:"+a,"account.artifacts.read:"+a));assertThat(holdings).hasSize(2);for(var h:holdings)assertThat(service.read(h,caller,java.time.Instant.now(),context).at("/reportedCostBasis/value").asText()).isIn("1484","14.34");var before=holdings.stream().map(Document::value).toList();sources.refresh(Set.of(a));assertThat(repo.list(Kind.HOLDING,Set.of(a)).stream().map(Document::value).toList()).isEqualTo(before);for(var c:repo.list(Kind.CONSTRUCTION,Set.of(a)))for(var leaf:leaves(c.value().path("composition")))assertThat(leaf.at("/allocation/basis/value").isNull()).isTrue();}
 }
 @Test void ambiguousAggregatedRowsAndMissingCostsRemainUnqualified()throws Exception{
  try(var db=new SqliteEvidenceStore(directory.resolve("bad.db").toString())){var accounts=new AccountDirectory(db.getConnection().getMetaData().getURL());String a=accounts.bind("pine","A1");var artifacts=new BrokerageArtifacts(db.getConnection().getMetaData().getURL(),JSON,new PositionReadService(db,JSON));var input=csv("A1,Pine,ETFs,ABC,Shares,50,620,-122,Cash,742,14.84\nA1,Pine,ETFs,ABC,Shares,50,620,-122,Cash,742,14.84\nA1,Pine,Options,-ABC261120C15,Call,-1,-25,-10.66,Cash,--,--\n");assertThat(artifacts.ingest(a,"source.csv","POSITIONS",input.getBytes(StandardCharsets.UTF_8),UUID.randomUUID().toString()).status()).isEqualTo("ACCEPTED");var repo=new PortfolioRepository(db,JSON);new PortfolioSources(repo,JSON,accounts).refresh(Set.of(a));var service=new PortfolioReadService(repo,new PortfolioSources(repo,JSON,accounts));var caller=new BearerAuthenticator.Principal("test",Set.of("account.holdings.read:"+a,"account.artifacts.read:"+a));for(var h:repo.list(Kind.HOLDING,Set.of(a)))assertThat(service.read(h,caller,java.time.Instant.now()).at("/reportedCostBasis/status").asText()).isEqualTo("INCOMPLETE");}
 }
 @Test void missingBasisDoesNotSuppressIndependentHistoricalSourceSpot()throws Exception{
  try(var db=new SqliteEvidenceStore(directory.resolve("spot.db").toString())){var accounts=new AccountDirectory(db.getConnection().getMetaData().getURL());String a=accounts.bind("pine","A1");var artifacts=new BrokerageArtifacts(db.getConnection().getMetaData().getURL(),JSON,new PositionReadService(db,JSON));var input=csv("A1,Pine,ETFs,ABC,Shares,100,1240,-244,Cash,--,--,12.40\n").replace("Average cost basis\n","Average cost basis,Last price\n");assertThat(artifacts.ingest(a,"source.csv","POSITIONS",input.getBytes(StandardCharsets.UTF_8),UUID.randomUUID().toString()).status()).isEqualTo("ACCEPTED");var repo=new PortfolioRepository(db,JSON);var service=new PortfolioReadService(repo,new PortfolioSources(repo,JSON,accounts));service.synchronize(Set.of(a));var caller=new BearerAuthenticator.Principal("test",Set.of("account.holdings.read:"+a,"account.artifacts.read:"+a));var holding=service.read(repo.list(Kind.HOLDING,Set.of(a)).getFirst(),caller,java.time.Instant.now());assertThat(holding.at("/reportedCostBasis/value").isNull()).isTrue();assertThat(holding.at("/reportedUnderlyingSpot/value").asText()).isEqualTo("12.4");assertThat(holding.at("/reportedUnderlyingSpot/asOf").isNull()).isTrue();assertThat(holding.at("/reportedUnderlyingSpot/observationDate").asText()).isEqualTo("2026-10-27");}
 }
}
